"""
Render every page of every source PDF at low DPI and OCR it, then classify
each page by type (paper1_mc, paper1_structured, paper2_mc_structured,
marking_scheme_p1, marking_scheme_p2, candidates_performance, cover, blank,
other) using keyword heuristics. Writes work/page_index.json for later
stages to consume, plus per-page OCR text cache under work/pages/.
"""
import fitz
import json
import os
import re
import subprocess
import sys
from pathlib import Path

BASE = Path("/Users/sinchunyeung/Documents-local/Materials/Phy/DSE")
YEAR_DIR = BASE / "Year"
WORK = BASE / "work"
PAGES_DIR = WORK / "pages"
PAGES_DIR.mkdir(parents=True, exist_ok=True)

# Explicit list of source files to process: (year, label, relative path)
SOURCES = []
for y in range(2012, 2023):
    if y == 2013 or y == 2014 or True:
        pass
for y in list(range(2012, 2023)) + [2024]:
    p = YEAR_DIR / str(y) / f"{y}.pdf"
    if p.exists():
        SOURCES.append((y, "combined", p))

for y, fname in [
    (2023, "2023 P1.pdf"), (2023, "2023 P2.pdf"), (2023, "2023 MS.pdf"), (2023, "2023 CP.pdf"),
    (2025, "2025 P1.pdf"), (2025, "2025 P2.pdf"), (2025, "2025 CP.pdf"),
    (2025, "2025 P1 Ans.pdf"), (2025, "2025 P2 Ans.pdf"),
    (2026, "2026 P1A.pdf"), (2026, "2026 P1B.pdf"), (2026, "2026 P2.pdf"),
]:
    p = YEAR_DIR / str(y) / fname
    if p.exists():
        SOURCES.append((y, fname.replace(".pdf", ""), p))


def ocr_page(doc, page_idx, dpi=100):
    pix = doc[page_idx].get_pixmap(dpi=dpi)
    png_path = PAGES_DIR / "_tmp.png"
    pix.save(png_path)
    try:
        out = subprocess.run(
            ["tesseract", str(png_path), "-", "--psm", "6"],
            capture_output=True, text=True, timeout=60,
        )
        return out.stdout
    except Exception as e:
        return f"[OCR ERROR: {e}]"


def classify(text):
    t = text.lower()
    score = {}
    if re.search(r"paper\s*2", t) and re.search(r"section\s*a", t) and "astronomy" in t:
        score["paper2_start"] = 1
    if "marking scheme" in t or "marking schemes" in t:
        score["marking_scheme_cover"] = 1
    if re.search(r"question no[.,]?\s*key", t) or re.search(r"key\s*question no", t):
        score["key_table"] = 1
    if "candidates' performance" in t or "candidates perform" in t or "candidates’ performance" in t:
        score["cp_cover"] = 1
    if "school-based assessment" in t or "school based assessment" in t:
        score["sba"] = 1
    if "acknowledgement" in t:
        score["ack"] = 1
    if "do not write on this page" in t:
        score["blank"] = 1
    if re.search(r"hong kong diploma of secondary education examination", t) and "physics" in t and len(t) < 400:
        score["cover"] = 1
    if re.search(r"paper\s*1\s*section\s*b", t) or "section b (conventional" in t:
        score["p1_section_b"] = 1
    if re.search(r"section\s*a\s*:\s*astronomy", t):
        score["p2_section_a"] = 1
    if re.search(r"section\s*b\s*:\s*atomic", t):
        score["p2_section_b"] = 1
    if re.search(r"section\s*c\s*:\s*energy", t):
        score["p2_section_c"] = 1
    if re.search(r"section\s*d\s*:\s*medical", t):
        score["p2_section_d"] = 1
    if re.search(r"multiple-choice questions", t):
        score["mc_page"] = 1
    return score


def main():
    index = {}
    for year, label, path in SOURCES:
        key = f"{year}_{label}"
        print(f"=== {key} ({path}) ===", flush=True)
        doc = fitz.open(str(path))
        n = len(doc)
        pages = []
        for i in range(n):
            text = ocr_page(doc, i)
            txt_path = PAGES_DIR / f"{key}_p{i:03d}.txt"
            txt_path.write_text(text)
            flags = classify(text)
            pages.append({"idx": i, "flags": flags, "chars": len(text)})
            if flags:
                print(f"  p{i}: {flags}", flush=True)
        index[key] = {"path": str(path), "n_pages": n, "pages": pages}
    (WORK / "page_index.json").write_text(json.dumps(index, indent=2))
    print("DONE")


if __name__ == "__main__":
    main()

